const server = http.createServer(async (request, response) => {
	const url = new URL(request.url, 'http://localhost');
	const route = url.pathname.replace(/^\/wled\/device/, '');
	const json = (data, code = 200) => { response.writeHead(code, { 'Content-Type': 'application/json' }); response.end(JSON.stringify(data)); };
	if (assets[route]) { response.writeHead(200, { 'Content-Type': assets[route][0] }); response.end(assets[route][1]); return; }
	if (!backendAvailable) { json({ error: 'not_found' }, 404); return; }
	if (request.method === 'GET') {
		if (route === '/wecker.json') json(config);
		else if (route === '/wecker/status') json(status());
		else if (route === '/wecker/sync/iphone/alarms') {
			++phoneListReadCount;
			if (phoneListError) json({ error: phoneListError }, 503);
			else json({ version: 2, supported: true, revision: phone?.revision || 0, mode: phone?.mode || 'single',
				capturedAt: phone?.capturedAt || null, alarms: phone?.mode === 'list' ? phoneAlarms : [] });
		}
		else if (route === '/wecker/log') {
			const offset = Number(url.searchParams.get('offset') || 0), limit = Number(url.searchParams.get('limit') || 24);
			const entries = history.slice(offset, offset + limit);
			json({ capacity: 96, total: 96, generation: 96, offset, entries, nextOffset: offset + entries.length < 96 ? offset + entries.length : null });
		}
		else if (route === '/presets.json') json({ 0: {}, 7: { n: 'Morning' }, 37: { n: '<svg onload=alert(1)>' } });
		else if (route === '/wecker/result') {
			const job = jobs.get(Number(url.searchParams.get('job')));
			if (!job) { json({ error: 'job_expired' }, 404); return; }
			if (++job.polls === 1) { json({ job: job.id }, 202); return; }
			if (!job.done) {
				job.done = true;
				if (job.error) job.code = 500;
				else if (job.route === '/wecker.json') {
					if (job.body.revision !== config.revision) { job.error = 'revision_conflict'; job.code = 409; }
					else { config = { ...job.body, revision: config.revision + 1 }; job.code = 200; }
				} else {
					if (job.body.action === 'presence-check') presence = 'present';
					if (job.body.action === 'preview') run = { active: true, preview: true, phase: 'rising', progress: 30, id: job.body.id };
					if (job.body.action === 'stop') run = { active: false, preview: false, phase: 'idle', progress: 0 };
					job.code = 200;
				}
			}
			json({ job: job.id, revision: config.revision, error: job.error }, job.code);
		} else json({ error: 'not_found' }, 404);
		return;
	}
	let body = '';
	for await (const chunk of request) body += chunk;
	const job = { id: nextJob++, route, body: JSON.parse(body), polls: 0, error: nextError };
	nextError = ''; jobs.set(job.id, job); json({ job: job.id }, 202);
});

